mapper.select:
SELECT p.id, p.product_name, p.category_id, c.category_name, p.merchant_id, m.merchant_name, m.region, p.price, p.stock, p.image, p.description, p.status, p.create_time, p.update_time FROM product p JOIN category c ON p.category_id = c.id JOIN merchant m ON p.merchant_id = m.id WHERE p.status = 1
AND p.category_id = #{categoryId}
AND m.region = #{region}
AND p.product_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY p.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM product p JOIN merchant m ON p.merchant_id = m.id WHERE p.status = 1
AND p.category_id = #{categoryId}
AND m.region = #{region}
AND p.product_name LIKE CONCAT('%', #{keyword}, '%')

mapper.update:
UPDATE product
SET stock = #{stock}
WHERE id = #{id}
  AND status = 1
